data class Item(val id: String, val leadTime: Int, val rule: String, val parameters: List<Long>, val safety: Long, val onHand: Long, val material: Long, val labor: Long, val description: String) {
    fun lotLabel() = when (rule) { "LFL" -> rule; "MIN" -> "MIN ${parameters[0]}/${parameters[1]}"; else -> "$rule ${parameters[0]}" }
}
fun lotParameters(rule: String, text: String): List<Long>? {
    val values = text.split('/').map(String::toLong)
    val valid = when (rule) { "LFL" -> values.size == 1 && values[0] == 0L; "MIN" -> values.size == 2 && values.all { it >= 1L }; else -> values.size == 1 && values[0] >= 1L }
    return if (valid) values else null
}
fun readItems(errors: MutableList<String>): Map<String, Item> {
    val items = sortedMapOf<String, Item>()
    for ((line, fields) in csvRows("items.csv")) {
        val id = fields[0]
        val rule = fields[2]
        val reason = when { id in items -> "duplicate item $id"; rule !in setOf("LFL", "FOQ", "POQ", "MIN") -> "unknown lot rule $rule"; lotParameters(rule, fields[3]) == null -> "bad lot parameter ${fields[3]} for $rule"; else -> null }
        if (reason != null) errors += "items.csv line $line: $reason"
        else items[id] = Item(id, fields[1].toInt(), rule, lotParameters(rule, fields[3])!!, fields[4].toLong(), fields[5].toLong(), fields[6].toLong(), fields[7].toLong(), fields[8])
    }
    return items
}
data class BomRow(val parent: String, val child: String, val quantity: Long, val scrap: Long) {
    fun need(parentQuantity: Long) = (parentQuantity * quantity * (100L + scrap) + 99L) / 100L
}
class Bom(items: Map<String, Item>) {
    val children = items.keys.associateWith { mutableListOf<BomRow>() }
    val parents = items.keys.associateWith { mutableListOf<BomRow>() }
    fun manufactured(id: String) = children.getValue(id).isNotEmpty()
    fun add(row: BomRow) {
        children.getValue(row.parent).add(row)
        children.getValue(row.parent).sortBy { it.child }
        parents.getValue(row.child).add(row)
        parents.getValue(row.child).sortBy { it.parent }
    }
    fun lowLevelCodes(): Map<String, Int> {
        val codes = mutableMapOf<String, Int>()
        fun code(id: String): Int {
            codes[id]?.let { return it }
            val value = parents.getValue(id).maxOfOrNull { code(it.parent) + 1 } ?: 0
            codes[id] = value
            return value
        }
        for (id in children.keys) code(id)
        return codes
    }
fun readBom(items: Map<String, Item>, errors: MutableList<String>): Bom {
    val bom = Bom(items)
    for ((line, fields) in csvRows("bom.csv")) {
        val parent = fields[0]
        val child = fields[1]
        val quantity = fields[2].toLong()
        val scrap = fields[3].toLong()
        var reason = when { parent !in items -> "unknown item $parent"; child !in items -> "unknown item $child"; quantity < 1 -> "bad quantity $quantity"; scrap > 50 -> "bad scrap $scrap"; parent == child -> "cycle $parent -> $parent"; bom.children.getValue(parent).any { it.child == child } -> "duplicate $parent -> $child"; else -> null }
        if (reason == null) bom.path(child, parent)?.let { reason = "cycle $parent -> ${it.joinToString(" -> ")}" }
        if (reason != null) errors += "bom.csv line $line: $reason"
        else bom.add(BomRow(parent, child, quantity, scrap))
    }
    return bom
}
data class WorkCenter(val id: String, val minutes: Long, val efficiency: Long, val description: String) { val available get() = minutes * efficiency / 100L }
data class Operation(val item: String, val number: Int, val center: String, val setup: Long, val run: Long) { fun minutes(quantity: Long) = setup + quantity * run }
fun readCenters(errors: MutableList<String>): Map<String, WorkCenter> {
    val centers = sortedMapOf<String, WorkCenter>()
    for ((line, fields) in csvRows("workcenters.csv")) {
        val id = fields[0]
        val efficiency = fields[2].toLong()
        val reason = when { id in centers -> "duplicate center $id"; efficiency !in 50L..150L -> "bad efficiency $efficiency"; else -> null }
        if (reason != null) errors += "workcenters.csv line $line: $reason"
        else centers[id] = WorkCenter(id, fields[1].toLong(), efficiency, fields[3])
    }
    return centers
}
fun readRoutings(items: Map<String, Item>, centers: Map<String, WorkCenter>, bom: Bom, errors: MutableList<String>): Map<String, List<Operation>> {
    val routings = mutableMapOf<String, MutableList<Operation>>()
    for ((line, fields) in csvRows("routings.csv")) {
        val id = fields[0]
        val number = fields[1].toInt()
        val center = fields[2]
        val run = fields[4].toLong()
        val reason = when { id !in items -> "unknown item $id"; center !in centers -> "unknown center $center"; !bom.manufactured(id) -> "purchased item $id"; run < 1 -> "bad run time $run"; routings[id].orEmpty().any { it.number == number } -> "duplicate $id operation $number"; else -> null }
        if (reason != null) errors += "routings.csv line $line: $reason"
        else routings.getOrPut(id) { mutableListOf() }.add(Operation(id, number, center, fields[3].toLong(), run))
    }
    return routings.mapValues { it.value.sortedBy { operation -> operation.number } }
}
fun operationWeek(receipt: Int, leadTime: Int, index: Int, count: Int) = maxOf(1, receipt - leadTime + index * leadTime / count)
